use {
    crate::models::{Attachment, IncidentSeverity, IncidentStatus, IncidentUpdate},
    chrono::{DateTime, Utc},
    serde::{Deserialize, Serialize},
    uuid::Uuid,
};

#[derive(Debug, Serialize, Deserialize, sqlx::FromRow, utoipa::ToSchema)]
pub struct Incident {
    /// Generated by the client, re-sending the same id never creates a duplicate
    pub id: Uuid,
    /// The client that owns the machine
    pub organization_id: Uuid,
    /// The organization whose support staff take it, the machine's manufacturer
    pub handled_by: Uuid,
    pub machine_id: Uuid,
    pub author_id: Uuid,
    pub author_name: String,
    pub description: String,
    pub severity: IncidentSeverity,
    pub status: IncidentStatus,
    /// Technician handling the incident, assigned by support staff
    pub assigned_to: Option<Uuid>,
    pub assigned_to_name: Option<String>,
    pub latitude: Option<f64>,
    pub longitude: Option<f64>,
    pub accuracy_m: Option<f32>,
    /// Device clock at the moment the incident was created, possibly offline
    pub reported_at: DateTime<Utc>,
    /// Server clock at the moment the incident was first received
    pub created_at: DateTime<Utc>,
    /// Bumped by any change, including new updates and attachments
    pub updated_at: DateTime<Utc>,
    #[sqlx(skip)]
    pub attachments: Vec<Attachment>,
    /// Status history and messages, oldest first
    #[sqlx(skip)]
    pub updates: Vec<IncidentUpdate>,
}
